  "Settings, lists and progress follow you between machines.":
    "सेटिंग्स, सूचियाँ और प्रगति अलग-अलग कंप्यूटरों पर भी आपके साथ रहती हैं।",
  "Settle the estate's affairs": "मृतक की संपत्ति के मामलों का निपटारा करें",
