  "Setup · {title}": "सेटअप · {title}",
  Severe: "गंभीर",
  Severity: "गंभीरता",
  "Sex & Nudity": "सेक्स और नग्नता",
  "Shader library": "शेडर लाइब्रेरी",
  Shaders: "शेडर",
  "Shaders (Anime4K + installed)": "शेडर (Anime4K + इंस्टॉल किए गए)",
  "Shaders installed": "शेडर इंस्टॉल किए गए",
  Shadow: "छाया",
  "Shape the metadata and reading language Harbor uses without changing your original files.":
    "अपनी मूल फ़ाइलें बदले बिना Harbor द्वारा उपयोग किए जाने वाले मेटाडेटा और पढ़ने की भाषा को अनुकूलित करें।",
  "Shape the sound without touching your system EQ. Applies on the mpv engine; the HTML5 engine plays audio untouched.":
    "अपने सिस्टम EQ को बदले बिना ध्वनि को मनचाहा बनाएँ। यह mpv इंजन पर लागू होता है; HTML5 इंजन ऑडियो को बिना बदलाव के चलाता है।",
  "Shape your anime feed.": "अपनी एनीमे फ़ीड को मनचाहा बनाएँ।",
  Share: "साझा करें",
  "Share a pack": "पैक शेयर करें",
  "Share a theme": "थीम शेयर करें",
  "Share an icon pack": "आइकन पैक शेयर करें",
  "Share collection": "कलेक्शन साझा करें",
  "Share diagnostics": "डायग्नोस्टिक्स शेयर करें",
  "Share list": "सूची साझा करें",
  "Share live watching status": "देखने का लाइव स्टेटस शेयर करें",
  "Share profile": "प्रोफ़ाइल साझा करें",
  "Share something with {group}": "{group} के साथ कुछ साझा करें",
  "Share to the community": "कम्युनिटी में साझा करें",
  "Share watch activity": "देखने की गतिविधि शेयर करें",
  "Share what you build and see who is using it.":
    "अपनी बनाई चीज़ साझा करें और देखें कि इसका इस्तेमाल कौन कर रहा है।",
  "Share what you think. [b]bold[/b], [img]https://...[/img], and links welcome.":
    "अपनी राय शेयर करें। [b]बोल्ड[/b], [img]https://...[/img] और लिंक इस्तेमाल कर सकते हैं।",
  "Share what you're watching, drop a recommendation, or announce a watch night.":
    "आप क्या देख रहे हैं, यह साझा करें, कोई सुझाव दें या साथ में देखने का कार्यक्रम घोषित करें।",
  "Share with {name}": "{name} के साथ साझा करें",
  "Share your thoughts (optional)": "अपने विचार साझा करें (वैकल्पिक)",
  Shared: "साझा किया गया",
  "Shared collections from across Harbor will show up here soon.":
    "पूरे Harbor से साझा किए गए कलेक्शन जल्द ही यहाँ दिखाई देंगे।",
  "Shared to the community": "कम्युनिटी में साझा किया गया",
  "Shared transition curves. Use anywhere you transition.":
    "साझा ट्रांज़िशन कर्व। जहाँ भी ट्रांज़िशन हो, इनका उपयोग करें।",
  "Sharing your diagnostics": "आपके डायग्नोस्टिक्स शेयर किए जा रहे हैं",
  "Sharing your diagnostics for issue #{ticket}. Your session tokens, API keys, and passwords are removed before anything leaves your device.":
    "समस्या #{ticket} के लिए आपके डायग्नोस्टिक्स शेयर किए जा रहे हैं। आपके डिवाइस से कुछ भी बाहर जाने से पहले आपके सेशन टोकन, API कुंजियाँ और पासवर्ड हटा दिए जाते हैं।",
  "Sharing your relay": "अपना रिले साझा करना",
  "Sharing {name}'s Stremio": "{name} का Stremio साझा किया जा रहा है",
  "Sharp Wit": "तीखी हाज़िरजवाबी",
  "Sharp comedies, sunny worlds, and the occasional binge bait.":
    "चुटीली कॉमेडी, खुशनुमा दुनिया और कभी-कभार लगातार देखने को लुभाने वाली सामग्री।",
  Sharpen: "शार्प करें",
  Sharpening: "शार्पनिंग",
  "Sharper lines and a little more pop.": "ज़्यादा शार्प लाइनें और थोड़ी ज़्यादा स्पष्टता।",
  "Sharper lines and cleaner gradients on anime, in real time. Heaviest on the graphics card of everything here.":
    "एनीमे में रीयल टाइम में ज़्यादा शार्प लाइनें और साफ़ ग्रेडिएंट। यहाँ मौजूद सभी विकल्पों में यह ग्राफ़िक्स कार्ड पर सबसे ज़्यादा भार डालता है।",
  "Sharper lines and cleaner gradients on anime, in real time. One-tap setup below.":
    "एनीमे में रीयल टाइम में ज़्यादा शार्प लाइनें और साफ़ ग्रेडिएंट। नीचे एक टैप में सेटअप उपलब्ध है।",
  "Sharper upscaling and smoother gradients in dark scenes, at the cost of more graphics-card load. Skip it on laptops and integrated graphics.":
    "डार्क सीन में ज़्यादा शार्प अपस्केलिंग और स्मूद ग्रेडिएंट, लेकिन ग्राफ़िक्स कार्ड पर अधिक भार पड़ेगा। लैपटॉप या इंटीग्रेटेड ग्राफ़िक्स वाले सिस्टम पर इसे छोड़ दें।",
  "Sharper, heavier.": "ज़्यादा शार्प, ज़्यादा लोड।",
  "Sharpest, heaviest.": "सबसे शार्प, सबसे ज़्यादा लोड।",
  Shelf: "शेल्फ़",
