  "Show Up Next on Simkl rail": "Simkl रेल पर अगला दिखाएँ",
  "Show a Minecraft card on your profile. Leave the username blank to hide it.":
    "अपनी प्रोफ़ाइल पर Minecraft कार्ड दिखाएँ। इसे छिपाने के लिए यूज़रनेम खाली छोड़ें।",
  "Show a Minecraft card with your username": "अपने यूज़रनेम वाला Minecraft कार्ड दिखाएँ",
  "Show a Skip Intro / Skip Credits button when Harbor detects one. Turn this off to never show it. You can also tap the X on the button to dismiss a wrong one for the rest of the episode.":
    "Harbor को इंट्रो या क्रेडिट मिलने पर इंट्रो छोड़ें / क्रेडिट छोड़ें बटन दिखाएँ। इसे कभी न दिखाने के लिए यह विकल्प बंद करें। अगर पहचान गलत हो, तो बाकी एपिसोड के लिए इसे हटाने हेतु बटन पर मौजूद X टैप करें।",
  "Show a Skip button when a known injected ad plays, and a small report button on new releases so you can mark ads for review.":
    "किसी पहचाने गए डाले हुए विज्ञापन के चलने पर छोड़ें बटन दिखाएँ, और नई रिलीज़ पर एक छोटा रिपोर्ट बटन दिखाएँ ताकि आप विज्ञापनों को समीक्षा के लिए चिह्नित कर सकें।",
  "Show a bookmark on saved titles": "सेव किए गए शीर्षकों पर बुकमार्क दिखाएँ",
  "Show a button on the detail page to mark a title or episode as watched. Syncs to Trakt and Simkl if connected.":
    "किसी टाइटल या एपिसोड को देखा हुआ चिह्नित करने के लिए विवरण पेज पर बटन दिखाएँ। कनेक्ट होने पर Trakt और Simkl के साथ सिंक होता है।",
  "Show a featured banner at the top of your library": "अपनी लाइब्रेरी के ऊपर फ़ीचर्ड बैनर दिखाएँ",
  "Show a laurel award tab on winning titles, like Netflix. Replaces the corner award chip and sits centered so it clears the rating and watchlist pills. Pick where it sits below.":
    "Netflix की तरह विजेता टाइटल पर लॉरेल अवॉर्ड टैब दिखाएँ। यह कोने के अवॉर्ड चिप की जगह लेता है और बीच में दिखता है, ताकि रेटिंग और वॉचलिस्ट पिल्स से न टकराए। नीचे चुनें कि इसे कहाँ दिखाना है।",
  "Show a lock control in the player that blocks mouse, keyboard, remote, and media-key input until you unlock it.":
    "प्लेयर में लॉक कंट्रोल दिखाएँ, जो तब तक माउस, कीबोर्ड, रिमोट और मीडिया-की इनपुट को ब्लॉक करता है, जब तक आप इसे अनलॉक न करें।",
  "Show a new code": "नया कोड दिखाएँ",
  "Show a quick volume overlay when you change volume with the player controls hidden, so keyboard and scroll wheel changes are always visible.":
    "प्लेयर कंट्रोल छिपे होने पर वॉल्यूम बदलते ही वॉल्यूम ओवरले दिखाएँ, ताकि कीबोर्ड और स्क्रॉल व्हील से किए गए बदलाव हमेशा दिखाई दें।",
  "Show a second subtitle in another language at the same time. Handy when you are learning a language: keep the one you are learning as your main subtitle, and put your own language here.":
    "एक ही समय में किसी दूसरी भाषा का दूसरा सबटाइटल दिखाएँ। भाषा सीखते समय यह उपयोगी है: जो भाषा आप सीख रहे हैं, उसे मुख्य सबटाइटल रखें और अपनी भाषा यहाँ रखें।",
