  "Slide {number}": "स्लाइड {number}",
  "Slide {n}": "स्लाइड {n}",
  Slider: "स्लाइडर",
  "Slightly lighter than background.": "बैकग्राउंड से थोड़ा हल्का।",
  Slot: "स्लॉट",
  "Slot is getting crowded ({count}/{limit}). May overflow on narrow screens.":
    "स्लॉट में भीड़ बढ़ रही है ({count}/{limit})। संकरी स्क्रीन पर सामग्री बाहर निकल सकती है।",
  "Slot is getting crowded ({n}/{limit}). May overflow on narrow screens.":
    "स्लॉट भरता जा रहा है ({n}/{limit})। संकरी स्क्रीन पर यह स्क्रीन से बाहर जा सकता है।",
  "Slow Burns": "धीरे-धीरे असर करने वाली कहानियाँ",
  "Slow Reveal": "धीरे-धीरे खुलासा",
  "Slow addons and P2P sources often need more than 10 seconds to start. Raise this if streams are being skipped before they get a fair chance.":
    "धीमे ऐडऑन और P2P स्रोतों को शुरू होने में अक्सर 10 सेकंड से ज़्यादा लगते हैं। अगर स्ट्रीम को पूरा मौका मिलने से पहले ही छोड़ा जा रहा हो, तो इसे बढ़ाएँ।",
  "Slow down a moment before posting again": "फिर से पोस्ट करने से पहले थोड़ा रुकें",
  "Slow or unstable connection": "धीमा या अस्थिर कनेक्शन",
  "Slow playback by 0.25x.": "प्लेबैक की गति 0.25x घटाएँ।",
  "Slow, strange, and absorbing. Best with the lights down low.":
    "धीमा, अजीब और मन को बाँध लेने वाला। कम रोशनी में सबसे अच्छा।",
  "Slow-Burn Dramas": "धीरे-धीरे असर करने वाले ड्रामा",
  "Slow-burn starts": "धीरे-धीरे असर करने वाली शुरुआतें",
  "Slow-burn worlds and bright chapters worth opening with coffee.":
    "धीरे-धीरे खुलती दुनियाएँ और रोशन अध्याय, जिन्हें कॉफ़ी के साथ शुरू करना अच्छा लगे।",
  "Slowly fade between a show's backdrop images while you read the page, instead of holding one still. Only runs when the show has more than one backdrop, and never when you have pinned one or asked for reduced motion.":
    "पेज पढ़ते समय शो की बैकड्रॉप इमेज को स्थिर रखने के बजाय उनके बीच धीरे-धीरे फ़ेड करें। यह केवल तभी चलता है जब शो में एक से अधिक बैकड्रॉप हों। किसी बैकड्रॉप को पिन करने या कम मोशन की सेटिंग चालू करने पर यह नहीं चलता।",
  "Small controls that sit around playback rather than in the picture.":
    "छोटे कंट्रोल, जो तस्वीर के भीतर नहीं बल्कि प्लेबैक के आसपास रहते हैं।",
  Smaller: "और छोटा",
  "Smaller releases worth surfacing": "छोटी रिलीज़ जो सामने लाने लायक हैं",
  "Smart resync with speech recognition": "स्पीच रिकग्निशन के साथ स्मार्ट री-सिंक",
  "Smooth motion": "स्मूद मोशन",
  "Smooth motion (interpolation) & SVP": "स्मूद मोशन (इंटरपोलेशन) और SVP",
  "Smooth motion runs on the bundled mpv engine in the Harbor desktop app. It has no effect in the browser.":
    "स्मूद मोशन Harbor डेस्कटॉप ऐप में शामिल mpv इंजन पर चलता है। ब्राउज़र में इसका कोई असर नहीं होता।",
  "Smooth on weak PCs": "कम क्षमता वाले PC पर भी स्मूद",
  "Smooth scrolling": "स्मूद स्क्रॉलिंग",
  "Smoothing off": "स्मूदिंग बंद",
