  "Soft blur with a floating pill.": "फ़्लोटिंग पिल के साथ सॉफ़्ट ब्लर।",
  "Soft grey": "हल्का स्लेटी",
  "Soft halo around the text. Cleanest on most content.":
    "टेक्स्ट के चारों ओर हल्की चमक। ज़्यादातर कॉन्टेंट पर सबसे साफ़ दिखता है।",
  "Soft shadow": "हल्की छाया",
  "Softer and dimmer, kinder for late-night watching.":
    "ज़्यादा सॉफ़्ट और मंद, देर रात देखने में आँखों के लिए आरामदायक।",
  "Softer restore. Kinder to compressed or noisy sources.":
    "हल्का रिस्टोरेशन। कंप्रेस्ड या नॉइज़ वाले स्रोतों के लिए बेहतर।",
  Solid: "सॉलिड",
  "Solid box": "सॉलिड बॉक्स",
  "Solid fill, no texture. Cleanest baseline.": "सॉलिड रंग, कोई टेक्सचर नहीं। सबसे साफ़ बेसलाइन।",
  "Some cam and new-release rips have ads spliced into the video itself. When the community has marked one, a Skip button appears. You can also report ads you spot for review. Off by default.":
    "कुछ कैम और नई रिलीज़ के रिप्स में विज्ञापन सीधे वीडियो के बीच जोड़े गए होते हैं। कम्युनिटी के किसी विज्ञापन को चिह्नित करने पर स्किप बटन दिखाई देता है। आपको जो विज्ञापन दिखें, उन्हें भी समीक्षा के लिए रिपोर्ट कर सकते हैं। डिफ़ॉल्ट रूप से बंद।",
  "Some copies of new releases have ads spliced into the video itself. This is experimental: the community marks where those ads are so others can skip them.":
    "नई रिलीज़ की कुछ कॉपी में विज्ञापन सीधे वीडियो के बीच जोड़े गए होते हैं। यह प्रयोगात्मक है: कम्युनिटी चिह्नित करती है कि वे विज्ञापन कहाँ हैं, ताकि दूसरे उन्हें छोड़ सकें।",
  Someone: "कोई व्यक्ति",
  "Someone I track has a new release": "मेरे ट्रैक किए गए किसी व्यक्ति की नई रिलीज़ आई है",
  "Something blew up while rendering. Reload to recover, or send us the technical detail.":
    "रेंडर करते समय कुछ गड़बड़ हो गई। ठीक करने के लिए रीलोड करें या हमें तकनीकी विवरण भेजें।",
  "Something else": "कुछ और",
  "Something unexpected went wrong. Nothing may have been written. Retry to re-check.":
    "कुछ अनपेक्षित गड़बड़ी हुई। हो सकता है कुछ भी सेव न हुआ हो। फिर से जाँचने के लिए दोबारा कोशिश करें।",
  "Something went wrong on the way there.": "वहाँ पहुँचने के दौरान कुछ गड़बड़ी हुई।",
  "Something went wrong reaching Harbor. Check your connection and try again.":
    "Harbor से कनेक्ट करते समय कुछ गड़बड़ी हुई। अपना कनेक्शन जाँचें और फिर कोशिश करें।",
  "Something went wrong reaching the ranking feed.": "रैंकिंग फ़ीड तक पहुँचने में कुछ गड़बड़ी हुई।",
  "Something went wrong.": "कुछ गड़बड़ी हुई।",
