  "Speed playback up by 0.25x.": "प्लेबैक की गति 0.25x बढ़ाएँ।",
  "Speed test": "स्पीड टेस्ट",
  "Speed up": "गति बढ़ाएँ",
  "Spinner stays forever and nothing in the player loads.":
    "स्पिनर लगातार घूमता रहता है और प्लेयर में कुछ भी लोड नहीं होता।",
