  "TMDB API key, v3 auth": "TMDB API कुंजी, v3 प्रमाणीकरण",
  "TMDB Rating": "TMDB रेटिंग",
  "TMDB asks for an app URL when you create the key. Put any URL at all, like https://harbor.app. The only thing you need back is the API key.":
    "कुंजी बनाते समय TMDB आपसे ऐप का URL माँगता है। कोई भी URL डालें, जैसे https://harbor.app। आपको केवल API कुंजी चाहिए।",
  "TMDB asks what the key is for. Choose Yes, this is for my own personal use only.":
    'TMDB पूछता है कि कुंजी किस लिए है। "हाँ, यह केवल मेरे निजी उपयोग के लिए है" चुनें।',
  "TMDB confirms the key is created. Follow the link it gives you to see your API key details.":
    "TMDB पुष्टि करता है कि कुंजी बन गई है। अपनी API कुंजी का विवरण देखने के लिए उसके दिए लिंक पर जाएँ।",
  "TMDB connected": "TMDB कनेक्ट हो गया",
  "TMDB connected. {n} streaming {services} on. Welcome aboard.":
    "TMDB कनेक्ट हो गया। {n} स्ट्रीमिंग {services} चालू हैं। स्वागत है।",
  "TMDB did not accept that key.": "TMDB ने वह कुंजी स्वीकार नहीं की।",
  'TMDB did not accept that key. Check you copied the "API Key (v3 auth)" value, not the read access token.':
    'TMDB ने वह कुंजी स्वीकार नहीं की। जाँचें कि आपने रीड एक्सेस टोकन नहीं, बल्कि "API Key (v3 auth)" का मान कॉपी किया है।',
  "TMDB did not accept that key. Check you copied the v3 key, not the read access token.":
    "TMDB ने वह कुंजी स्वीकार नहीं की। जाँचें कि आपने रीड एक्सेस टोकन नहीं, बल्कि v3 कुंजी कॉपी की है।",
  "TMDB has no notable releases for this month and region.":
    "TMDB पर इस महीने और क्षेत्र के लिए कोई उल्लेखनीय रिलीज़ नहीं है।",
  "TMDB is aboard.": "TMDB जुड़ गया है।",
  "TMDB is connected. Your TV has it.": "TMDB कनेक्ट है। अब यह आपके TV पर है।",
  "TMDB is temporarily unavailable, so these results may be incomplete.":
    "TMDB अस्थायी रूप से उपलब्ध नहीं है, इसलिए ये नतीजे अधूरे हो सकते हैं।",
  "TMDB is temporarily unavailable. Try your search again shortly.":
    "TMDB अस्थायी रूप से उपलब्ध नहीं है। थोड़ी देर बाद फिर खोजें।",
  "TMDB key": "TMDB कुंजी",
  "TMDB may show a captcha while you register. Complete it to carry on.":
    "रजिस्टर करते समय TMDB कैप्चा दिखा सकता है। आगे बढ़ने के लिए इसे पूरा करें।",
  "TMDB powers the firehose of every release this month. The free tier covers it. About 60 seconds to set up. Switch to My Library if you'd rather only see what you've saved.":
    "TMDB इस महीने की हर रिलीज़ की जानकारी उपलब्ध कराता है। इसके लिए मुफ़्त टियर काफ़ी है। सेटअप में लगभग 60 सेकंड लगते हैं। अगर आप केवल सेव किए हुए शीर्षक देखना चाहते हैं, तो मेरी लाइब्रेरी पर जाएँ।",
  "TMDB · catalogs and rails": "TMDB · कैटलॉग और पंक्तियाँ",
  TRACKS: "ट्रैक",
  "TTF, OTF, WOFF or WOFF2": "TTF, OTF, WOFF या WOFF2",
  TV: "TV",
  "TV Genre": "TV शैली",
  "TV Guide": "TV गाइड",
  "TV Series": "TV सीरीज़",
  "TV Settings": "TV सेटिंग्स",
  "TV Short": "TV लघु फ़िल्म",
  "TV Shows": "TV शो",
  "TV Shows · {n}": "TV शो · {n}",
  "TV guide": "TV गाइड",
  "TV navigation": "TV नेविगेशन",
  "TV navigation in player": "प्लेयर में TV नेविगेशन",
  "TV only": "केवल TV",
  "TV only. Older sets crop the outer edge of the picture. Nudge Harbor inward until nothing is cut off.":
    "केवल TV। पुराने TV सेट तस्वीर के बाहरी किनारे काट देते हैं। Harbor को अंदर की ओर खिसकाएँ, जब तक कुछ भी न कटे।",
  "TV shows wide art cards with the logo on them. Poster is the classic grid.":
    "TV विकल्प में लोगो वाले चौड़े आर्ट कार्ड होते हैं। पोस्टर विकल्प में पारंपरिक ग्रिड होता है।",
  "TV uses wide rounded cards with the logo on the art, like a TV home screen. Poster is the classic grid.":
    "TV विकल्प में TV होम स्क्रीन जैसे चौड़े, गोल किनारों वाले कार्ड होते हैं, जिनकी आर्ट पर लोगो होता है। पोस्टर विकल्प में पारंपरिक ग्रिड होता है।",
  TVDB: "TVDB",
  "TVDB list": "TVDB सूची",
  "TVDB lists are unavailable right now.": "TVDB सूचियाँ अभी उपलब्ध नहीं हैं।",
  "TVDB order": "TVDB क्रम",
