  Taiwanese: "ताइवानी",
  "Take me back": "मुझे वापस ले जाएँ",
  "Take the short API Key at the very bottom, not the long API Read Access Token above it.":
    "सबसे नीचे दी गई छोटी API कुंजी लें, उसके ऊपर वाला लंबा API रीड एक्सेस टोकन नहीं।",
