  Tap: "टैप करें",
  "Tap a line to jump there, then nudge until the subtitles match what you hear.":
    "वहाँ जाने के लिए किसी पंक्ति पर टैप करें, फिर सबटाइटल को सुनाई दे रही आवाज़ से मिलाने तक थोड़ा आगे-पीछे करें।",
  "Tap a line, then nudge": "किसी पंक्ति पर टैप करें, फिर थोड़ा आगे-पीछे करें",
  "Tap a profile to switch": "बदलने के लिए किसी प्रोफ़ाइल पर टैप करें",
  "Tap a star to change, then save": "बदलने के लिए किसी स्टार पर टैप करें, फिर सेव करें",
  "Tap a star to rate": "रेटिंग देने के लिए किसी स्टार पर टैप करें",
  "Tap again to clear": "साफ़ करने के लिए फिर टैप करें",
  "Tap again to delete {n} rules": "{n} नियम डिलीट करने के लिए फिर टैप करें",
  "Tap again to remove all {n} extensions": "सभी {n} एक्सटेंशन हटाने के लिए फिर टैप करें",
  "Tap again to reset everything": "सब कुछ रीसेट करने के लिए फिर टैप करें",
  "Tap again to reset {n}": "{n} को रीसेट करने के लिए फिर टैप करें",
  "Tap again to reset {n} badges": "{n} बैज रीसेट करने के लिए फिर टैप करें",
  "Tap anywhere to cancel": "रद्द करने के लिए कहीं भी टैप करें",
  "Tap one until your show plays nice and clear!":
    "किसी एक पर टैप करते रहें, जब तक आपका शो साफ़ और ठीक से न चले!",
  "Tap the first and last line of the section, then tap the line playing now and Sync from here.":
    "सेक्शन की पहली और आखिरी पंक्ति पर टैप करें, फिर अभी चल रही पंक्ति पर टैप करके यहाँ से सिंक करें।",
  "Tap the first line of the section you want to fix.":
    "जिस सेक्शन को ठीक करना है, उसकी पहली पंक्ति पर टैप करें।",
  "Tap the genres you want more of. They steer the Top Picks row at the top of this page.":
    "जिन शैलियों की और सामग्री चाहते हैं, उन पर टैप करें। इनसे इस पेज के ऊपर मौजूद टॉप पिक्स पंक्ति तय होती है।",
  "Tap the heart on any movie, show, manga, or character to save it here.":
    "किसी भी फ़िल्म, शो, मांगा या किरदार को यहाँ सेव करने के लिए उस पर बने दिल को टैप करें।",
  "Tap the page to bookmark": "बुकमार्क करने के लिए पेज पर टैप करें",
  "Tap the star on any manga to save it here.":
    "किसी भी मांगा को यहाँ सेव करने के लिए उस पर बने स्टार को टैप करें।",
  "Tap the star on any movie, show, or manga, or the heart on a character, to save it here.":
    "किसी भी फ़िल्म, शो या मांगा पर बने स्टार या किसी किरदार पर बने दिल को टैप करके उसे यहाँ सेव करें।",
  "Tap to switch": "बदलने के लिए टैप करें",
  "Tap to switch. The pencil renames, recolors, or adds a PIN.":
    "बदलने के लिए टैप करें। पेंसिल से नाम या रंग बदला जा सकता है या PIN जोड़ा जा सकता है।",
