  "Telegram sends through a bot you create. You need two things: a":
    "Telegram आपके बनाए बॉट के ज़रिए भेजता है। आपको दो चीज़ें चाहिए: एक",
  "Telesync rip": "टेलीसिंक रिप",
  "Television Award": "टेलीविज़न पुरस्कार",
  "Television's finest": "टेलीविज़न के सर्वश्रेष्ठ",
  "Tell people what changed in this version. Reviewers see it too.":
    "लोगों को बताएँ कि इस वर्ज़न में क्या बदला है। समीक्षक भी इसे देखेंगे।",
  "Telling your boss you're quitting": "अपने बॉस को बताना कि आप नौकरी छोड़ रहे हैं",
  Template: "टेम्पलेट",
  "Temporary files": "अस्थायी फ़ाइलें",
  "Tennis tournaments": "टेनिस टूर्नामेंट",
  "Tense Performances": "तनावपूर्ण अभिनय",
  Test: "टेस्ट",
  "Test badge rules (Try it)": "बैज नियम टेस्ट करें (आज़माएँ)",
  "Test connection": "कनेक्शन टेस्ट करें",
  "Test controller": "कंट्रोलर टेस्ट करें",
  "Test failed": "टेस्ट विफल",
  "Test mode: your controller only moves this diagram. Press Esc to stop.":
    "टेस्ट मोड: आपका कंट्रोलर केवल इस डायग्राम को हिलाता है। रोकने के लिए Esc दबाएँ।",
