  "This session cannot refresh its token. Sign out and back in, or the TV will never see these changes.":
    "यह सेशन अपना टोकन रीफ़्रेश नहीं कर सकता। साइन आउट करके फिर से साइन इन करें, वरना TV को ये बदलाव कभी नहीं दिखेंगे।",
  "This sets the interface, metadata, subtitle, and audio languages to match.":
    "यह इंटरफ़ेस, मेटाडेटा, सबटाइटल और ऑडियो की भाषाओं को एक जैसा सेट करता है।",
