  "Tune picks": "पिक्स को बेहतर बनाएँ",
  "Tune the size and corner radius of every poster across Home, Discover, and your library. The preview updates live.":
    "होम, डिस्कवर और अपनी लाइब्रेरी में हर पोस्टर का आकार और कोनों की गोलाई अनुकूलित करें। प्रीव्यू तुरंत अपडेट होता है।",
  "Tune your Top Picks": "अपने टॉप पिक्स को बेहतर बनाएँ",
  "Tune your picks": "अपने पिक्स को बेहतर बनाएँ",
