  services: "सेवाएँ",
  shown: "दिखाया गया",
  "signed in": "साइन इन हैं",
  "sketchy files": "संदिग्ध फ़ाइलें",
  skipped: "छोड़ा गया",
  "skipped {n} anime": "{n} ऐनिमे छोड़े गए",
  "so pick one you'll keep.": "इसलिए वही चुनें जिसे आप रखना चाहेंगे।",
