  soon: "जल्द",
  speed: "गति",
  "sports.customize": "कस्टमाइज़ करें",
  "sports.customize.all": "सभी",
  "sports.customize.cancel": "रद्द करें",
  "sports.customize.clearAll": "सभी साफ़ करें",
